export function TemplateIconsSprite() {
    return (
        <div style={{ display: 'none' }}>
            <style>{`
                symbol path, symbol ellipse, symbol circle, symbol polygon, symbol polyline {
                    stroke: currentColor !important;
                }
            `}</style>
            <div dangerouslySetInnerHTML={{ __html: TEMPLATE_ICONS_SPRITE_HTML }} />
        </div>
    );
}

export function BoxModelIcon({ modelId, className = "w-5 h-5" }) {
    const iconId = `#icon-${modelId}`;
    return (
        <svg className={`shrink-0 ${className}`} viewBox="0 0 24 24" style={{ fill: 'none', stroke: 'currentColor' }}>
            <use href={iconId} xlinkHref={iconId} />
        </svg>
    );
}
